custom_css:
/*【缘于雪】作者：易碎蝶
①本美化免费发布于尾巴镇（冬雪杯作品），禁止二传二改倒卖，使用二传美化我也不会原谅，如果你是买来的恭喜你为二传做了贡献
②部分代码用到了其他老师分享的，有标注~
③仅限于在正规渠道由本人发布后下载获取，一切其他方式获得皆视为二传，抓到必究
④用我美化的内鬼祝你全家暴毙口牙*/


/* ====== 全局字体====== */
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

body {
    font-family: "Noto Serif CJK";
    font-weight: normal;
    /* font-feature-settings: "hwid"; 启用等宽变化字形 */
}

/*———————— 顶栏 ————————*/
#top-bar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 0px;
    pointer-events: none;
    z-index: 1000; /* 确保足够高的层级 */
    background: none;
    border: 0;
    box-shadow: none;
    overflow: visible;
}

#top-bar::before {
    content: "";
    position: fixed;
    top: 0px; 
    left: 0px; 
    width: calc(100% - 0px);
background: rgba(0, 0, 0, 0.6); 
  backdrop-filter: blur(17px) !important;
    border-radius:  0px; 
    box-shadow: 
        0 0 0 1px rgba(155,191, 255, 1),
        0px 0px 16px rgba(79,126, 195, 0.3);
    z-index: 4; 
    pointer-events: auto;
}


@media (max-width: 768px) {
    #top-bar {
        height: 0px; 
    }

    #top-bar::before {
        height: 30px;/*顶栏高度*/
    }
}



/* ⭕️顶栏装饰层 */
#top-bar::after {
      pointer-events: none; /* 点击会穿透到下层元素 */
    content: "";
    position: fixed;
    background: url("") no-repeat center / contain;
    width: 260px;
    height: 200px;
    top: -65px;
    right: 80px;
    z-index: 6;

    transform-origin: top center;
}






/* —————面板背景———— */
.drawer-content {
 background-image: url('https://iili.io/fcBTgSe.jpg'); /* 面板背景 */
  background-size: cover; 
  background-position: center; 
  background-repeat: no-repeat; 
  background-attachment: fixed; 
}


/* ===== ⭕️楼层箭头、计数器核心 ===== */
.fa-chevron-right:before,
.fa-chevron-left:before,
.fa-arrow-right:before {
  content: "" !important;
  display: none !important; 
}

.fa-chevron-left,
.fa-chevron-right {
  display: inline-block;
  width: 20px;
  height: 20px; 
  min-width: 0;
  opacity: 1 !important; 
  background: center/contain no-repeat;
}

.fa-chevron-left {
  background-image: url('https://iili.io/fcfBLEG.png'); /* 左 */
  margin-bottom: -12px; 

padding: 0px 0px 0;
}
.fa-chevron-right {
  background-image: url('https://iili.io/fcfBLEG.png'); /* 右 */
  top: 50% !important;
  left: 0% !important;
  transform: translate(-90%, -35%) !important;
  z-index: 9999 !important;
}
/* ===== 楼层计数器样式 ===== */
.swipes-counter {
  font-size: 9px;
  font-weight: 540;
  opacity: 1 !important;
  color: #C1D4FF !important;
}
.swipes-counter {
  position: absolute;
  top: -0px;
  right: 56px;
  z-index: 9999;
  pointer-events: none;
}

/* ==============================================
🦋气泡拼接开始🦋 *==============================================*/

/* 🍃上层装饰层、拼接气泡顶部 */
.mes::before {
  content: "";
  position: absolute;
  top: -30px; /* 【上下】(负值向上) */
  left: -0px; /* 【左右】 */
  width: 368px; /* 【宽度/大小】 */
  height: 590px; /* 【高度/大小】 */
  background-image: url('https://iili.io/fc3C40Q.png'); 
  background-size: contain; 
  background-repeat: no-repeat; 
  z-index: -2; 
  pointer-events: none; 
}


/* 🍃 中层气泡*/
.mes {
   z-index: -3;
  max-width: 365px;/*【🍃宽度】*/
  width: 100%;/*【👁宽度，一般调整第一个就行，没效果再调整这个】*/
  margin: 40px auto 20px;/*【AI和用户的气泡距离⭕️第一个是调整最早的消息与顶部的距离防止顶部超过屏幕】*/
  border-radius: 0px;
  background-size: 100% auto; 
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  position: relative;
  overflow: visible;
  box-shadow: none !important; 
  box-shadow: 
    0 0 0 0px #9BBFFF,
    0 0 20px rgba(61, 109, 184, 0.2) !important; 
}
.mes:hover {
  transform: scale(1);         /* 放大效果 */
  box-shadow: 
    0 0 0 0px #5a0000,           /* 悬停边框 */
    0 0 35px rgba(61, 109, 184, 0.5) !important; 
}
/*毛玻璃@LiitleYE*/
body.no-blur .mes {
background: rgba(0, 0, 0, 0.5); 
  backdrop-filter: blur(20px) !important;
}
/* 🍃下层装饰层、拼接气泡尾部 */
.mes::after {
  content: "";
  position: absolute;
  bottom: -48px; /* 【上下】(负值向下) */
  right: -0px; /* 下层装饰层【左右】 */
  width: 363px; /* 【宽度/大小】 */
  height: 181px; /* 【高度/大小👁会影响最新消息的底部留白，不可调太高，宽度拉不动再调高一点】 */
  background-image: url('https://iili.io/fc2P7iQ.png'); 
background-size: contain; 
  background-repeat: no-repeat;
  z-index: -4; 
  pointer-events: none; 
}

/*——————🍃文本边距——————*/

 .mes_text,
.mes_reasoning {
    font-weight: 300; 
    line-height: 1.9; /* 行高 */
    text-align: justify; 
    text-justify: inter-word; 
    overflow-wrap: anywhere;
    hyphens: auto; 

    /* 优化后的间距系统 */
    --top-padding: 16rem;    /* 顶部 */
    --bottom-padding: 2rem; /* 底部 */
    --left-padding: 0rem;  /* 左侧 */
    --right-padding: 0.6rem; /* 右侧 */


    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);

    max-width: 100ch;

    margin: 0 auto; 

    /* 高级排版增强 */
    font-kerning: normal; 
    letter-spacing: 0.01em; 
    text-rendering: optimizeLegibility; 
}

.mes_reasoning::first-letter {
    font-weight: 600;
    margin-right: 0.5em;
}
/*@咩野老师*/
.mes_text {
  /* 文字两端对齐justify，左对齐改成left，居中改成center  */
  text-align: justify;
}

/* ==============================================
🦋气泡拼接结束🍃头像美化开始============================================== */


/*⭕️头像框*/
.mesAvatarWrapper {
  position: absolute;
  top: -147px;
  left: 48.9%;
  transform: translateX(-50%);
  z-index: -1;
  width: 70px;  
  height: 70px; 
  overflow: visible; 
}

/* ⭕️头像框位置与大小调整核心 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 122%;/* 【上下】 */
  left: 148%;/* 【左右】 */
  width: 410%;  /* 【框宽度】 */
  height: 380%; /* 【框高度】 */
  display: block;

  /* ⭕️头像框链接放置处 */
  background-image: url('https://iili.io/fc2PE5F.png');/*←🍃*/
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
  transform: translate(-50%, -50%);
  z-index: 1; 

}

.mesAvatarWrapper img {
  position: relative;
  z-index: -1; 
}

/* ⭕️头像位置 */
.mesAvatarWrapper {
  position: absolute;
  top: -5px;           /* 【负值向上】 */
  left: 39%;            /* 【头像左右】 */
  transform: translateX(-50%);
  z-index: -1;
    filter: 
    saturate(1) !important;
}

/* ⭕️头像尺寸*/
.mesAvatarWrapper .avatar {
  /* 🍃头像尺寸 */
  width: 149px;           /* 宽度 */
  height: 149px;          /* 高度 */
  transform: rotate(-7deg); /* 旋转 */
}
.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ⭕user设置页面/角色选择头像美化⭕*/
/*收藏头像黄圈隐藏、名字颜色修改@Little YE*/
.character_select.is_fav .avatar {
  outline: none !important;
}
.character_select.is_fav .ch_name {
  color: #6CA2FF !important;
}
.avatar img {
    border: 0px solid white; /* 头像描边 */
box-shadow: 
  inset -0px -3px 3px rgba(245, 189, 206, 0),
  0px 6px 5px rgba(255, 255, 255, 0),
  0px 8px 8px rgba(245, 189, 206, 0);
}

/* user */
.avatar-container {
    position: relative; 
    border-radius: 0px;
    background: rgba(0, 0, 0,0.3) !important;
border: 0px solid #fff;
    color: #C1D4FF;
box-shadow: 
  inset -0px -3px 3px rgba(245, 189, 206, 0),
  0px 6px 5px rgba(255, 255, 255, 0),
  0px 2px 4px rgba(0, 0, 0, 0.7);

    filter: 
    saturate(1) !important;
}


.avatar-container::after {
    content: '';
    position: absolute;
    top: 0px;
    right: 0px;
    width: 50px; 
    height: 50px; 
    background: url('') center/cover no-repeat; 
    transform: translate(30%, -30%); 
}
.avatar-container {
  position: relative;
  overflow: visible !important;
}
/* char */
.bogus_folder_select,
.character_select {
    position: relative;
border-radius: 0px;
    margin-bottom: 20px;
background: rgba(0, 0, 0,0.3) !important;
border: 0px solid #fff;
    color: #C1D4FF;
    box-shadow: 
  inset -0px -3px 3px rgba(245, 189, 206, 0),
  0px 6px 5px rgba(255, 255, 255, 0),
  0px 2px 4px rgba(0, 0, 0, 0.7);
    filter: 
    saturate(1) !important;
}
.bogus_folder_select,
.character_select::after {
    content: '';
    position: absolute;
    top: 0px;
    right: 0px;
    width: 40px; 
    height: 40px; 
    background: url('') center/cover no-repeat; 
    transform: translate(30%, -30%); 
}
.bogus_folder_select::after,
.character_select::after {
}
bogus_folder_select,
.character_select {
  position: relative;
  overflow: visible !important;
}

/* ==============================================
🦋头像美化结束🍃文字效果美化开始============================================== */
/*去除提示词阴影@①点这里*/

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
filter: none;
}

/* === 设置选项=== */
small {
  color: #C1D4FF !important;
  opacity: 1;
}
.toggle-description {
    color: #C1D4FF;
}
#completion_prompt_manager .completion_prompt_manager_header div {
    color: #C1D4FF; /*字符*/
}

.fa-solid::before, .fa-regular::before {
    vertical-align: middle;
    text-align: center;
}

.right_menu_button {
    padding: 0px;
    filter: none;
    color: #C1D4FF !important; /* 更新文字颜色 */
}

/*世界书激活时按钮颜色*/
.world_set, .toggleEnabled {
    color: #6CA2FF !important;
}
/*角色收藏时按钮颜色*/
.fav_on {
    color: #6CA2FF !important;
}
/* === 预设区文字颜色 === */
/* 选中 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #9BBFFF;
}

/* 未选 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, 
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #A1B0C8;
}

/* 星号等标识颜色*/
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: #585858;
}

/* 代码块 */
code, pre {
  background: rgba(0, 0, 0,0.3) !important;
  color: #C1D4FF !important; 
  border: 0px solid #ffffff !important; 
box-shadow: 
  inset -0px -0px 7px rgba(245, 189, 206, 0),
  0px 3px 5px rgba(255, 255, 255, 0),
  0px 0px 8px rgba(61, 109, 184, 0.2);
  border-radius: 0px !important; 
line-height: 1.5; 
}


code, pre {
  position: relative;
  overflow: visible !important;
}
/* 引用气泡 */
.mes_text q {
  background: rgba(82, 128, 204,0.1) !important; 
border: 0px solid #ffffff !important;
box-shadow: 
    inset 0px 1px 0px rgba(255, 255, 255, 0), 
    2px 2px 10px rgba(0,0,0, 0.2) !important;
  border-radius: 0px 0px 0px 0px !important;
font-weight: 500;
line-height: 1.5;
}


/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
  border-left:2px solid #9BBFFF !important;
  background: rgba(0, 0, 0,0.3) !important;
  color: #C1D4FF !important; 
  box-shadow: 
    inset 2px -0px 0px rgba(0, 0, 0,0.7),
    -3px -3px 4px rgba(245, 189, 206, 0);
  border-radius: 0px !important; 

}
/* 斜体 */
em, i {
  background: linear-gradient(to bottom, 
    rgba(255, 255, 255, 0) 90%, 
    rgba(150, 114, 133, 0) 90%) !important; 
}
/* ==============================================
🦋文字效果美化结束🍃零碎美化开始============================================== */

/*—— 🍃楼层 ——*/


.mes .mesIDDisplay {
    position: fixed;
    top: 52px;
    left: 171.5px;                    /* 从左侧开始定位 */
  transform: none;            /* 移除所有变换效果 */
    z-index: 2;
    margin-top: 0px;
    text-align: left;           /* 文字左对齐 */
    width: auto;                /* 宽度自适应内容 */
    white-space: nowrap;        /* 防止文字换行 */
    padding: 0 10px;            /* 添加左右内边距 */
    display: inline-flex; 
    align-items: center;  
    gap: 2px;            /* 【左右文字间距】 */

    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.65);
    font-weight: 300;
    color: #C1D4FF;      /* 【颜料🎨】【主文字颜色】 */
transform: rotate(0deg); /* 旋转 */
}


/* 左侧文字 */
.mes .mesIDDisplay::before {
    content: var(--left-text, "思念"); /* 【左侧文字内容】 */
    white-space: nowrap;  
    color: var(--left-color, #C1D4FF); /* 【颜料🎨】【左侧文字颜色】 */
    font-weight: 300;
}

/* 右侧文字 */
.mes .mesIDDisplay::after {
    content: var(--right-text, "天"); /* 【右侧文字内容】 */
    white-space: nowrap;  
    color: var(--right-color, #C1D4FF); /* 【颜料🎨】【右侧文字颜色】 */
    font-weight: 300;
}

/*—— 🍃基础信息【时间戳、角色昵称等】 ——*/

/* ⭕️消息文字上边距留白核心调整 */
.mes_block {
  position: relative;
  margin-top: -120px;  
  overflow: visible;
}

/* ⭕️角色名称核心调整 */
.mes_block .ch_name {
  position: relative;
  top:195.8px; /* 上下 */
  left: 25px;
  max-width: calc(100% - 105px); 
  min-height: 0px;
  z-index: 10; 
  font-size: 0.70em;
  font-weight: 300;
  letter-spacing: 0.9px;
  white-space: nowrap;
  transform: rotate(0deg); /* 旋转 */
  color: #C1D4FF !important; 
  text-shadow: none !important;
  -webkit-text-stroke: 0 !important;
}
/* 左侧文字 */
.mes_block .ch_name::before {
  content: "";       /*左侧文字 */
  font-size: 1em;
  color: #E9D6EF;            /* 左侧文字颜色 */
  display: inline;
  padding-right: 0px;        /* 右侧间距（分隔时间戳） */
  pointer-events: none;
}

/* ⭕️时间戳核心调整 */
.timestamp {
  position: absolute;
  top: 255px;                /* 上下 */
  left: 353px;                /* 左右 */
  width: 300%; 
  font-size: 0.95em;            /* 字体大小 */
  font-weight: 300;          /* 字体粗细 */
  transform: rotate(0deg);   /* 旋转 */
  white-space: nowrap;
  color: #7A7A7A !important; 
  opacity: 1 !important;
}

/* 左侧文字 */
.timestamp::before {
  content: "";       /*左侧文字 */
 font-size: 1em;
  color: #F3DAE5;            /* 左侧文字颜色 */
  display: inline;
  padding-right: 0px;        /* 右侧间距（分隔时间戳） */
  pointer-events: none;
}

/* 右侧文字 */
.timestamp::after {
  content: "";       /* 右侧文字 */
font-size: 1em;
  color: #F3DAE5;            /* 右侧文字颜色 */
  display: inline;
  padding-left: 0px;         /* 左侧间距（分隔时间戳） */
  pointer-events: none;
}


/* ⭕️编辑按钮核心调整 */
.mes_buttons {
  position: relative;
  top: 33px; /*上下*/
  left: 90px;/*左右*/
  z-index: 30;
  padding: 20px; 
  min-height: 36px;
  box-sizing: border-box;
  transform: rotate(0deg); /* 旋转 */
}

.mes_edit_buttons {
    display: none;
    flex-direction: row;
    column-gap: 5px;
    float: right;
    cursor: pointer;
    padding-bottom: 5px;
    filter: none; /*移除阴影*/
    transition: 0.3s ease-in-out;

    /* ⭕编辑菜单位置核心调整⭕ */
    position: relative;
    top: 105px;  /* 负数上移 | 正数下移  */
    right: -10px;   /* 负数右移 | 正数左移  */

  transform: rotate(-0deg); /* 旋转 */
}
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable.disabled {
    filter: none !important;
}
.mes_button, .extraMesButtons>div {
cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: none !important;
    /* ⭕设置省略号菜单颜色 */
    color: #C1D4FF !important;
opacity: 0.9 !important; 
}

/*—— 计时器&字符——*/
.mes {
  position: relative; 
}

.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: fixed; 
  z-index: 3; 
  cursor: default;
opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 0.65);/*文字大小*/
  font-weight: 300;/*文字粗细*/
  padding: 0;
  top: var(--element-top, 240px);
  left: var(--element-left, 50%);
  transform: translateX(var(--element-translate, -50%));
transform: rotate(0deg); /* 旋转 */
}


/* === ⭕️计时器核心 === */
.mes .mes_timer {
  --element-top: var(--timer-top, 90px); /*【🍃计时器上下】*/
  --timer-left: 181.5px; /* 🍃计时器左右 */
--timer-translate: 0; 
  text-align: left; 
  left: var(--timer-left);
  transform: translate(var(--timer-translate), -50%);

  /* 文字内容控制 */
  --timer-prefix: "心绪"; /* 【🍃前缀】 */
  --timer-suffix: "时"; /* 【🍃后缀】 */

  --timer-main-color: #C1D4FF; /* 【🍃计时器颜色】 */
  --timer-prefix-color: #C1D4FF; /* 【🍃前缀颜色】 */
  --timer-suffix-color: #C1D4FF; /* 【🍃后缀颜色】 */

  color: var(--timer-main-color);
}

/* 计时器文字控制 */
.mes .mes_timer::before {
content: var(--timer-prefix); /* 前缀文字 */
  color: var(--timer-prefix-color);
  padding-right: 0px;
}
.mes .mes_timer::after {
  content: var(--timer-suffix); /* 后缀文字 */
  color: var(--timer-suffix-color);
  padding-left: 0px;
}

/* === 字符计数器单独设置 === */
.mes .tokenCounterDisplay {
  text-align: left;
  --element-top: var(--counter-top, 68px); /* 【🍃字符计数器上下】 */
  --element-left: var(--counter-left, 259.5%); /* 【🍃字符计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: "雪花"; /* 【🍃前缀】 */
  --counter-suffix: "片"; /* 【🍃后缀】 */

  --counter-main-color: #C1D4FF; /* 【🍃计数器颜色】 */
    --counter-prefix-color: #C1D4FF; /* 【🍃前缀颜色】 */
  --counter-suffix-color: #C1D4FF; /* 【🍃后缀颜色】 */
  color: var(--counter-main-color);

}

.mes .tokenCounterDisplay::before {
  content: var(--counter-prefix); /* 前缀文字 */
  color: var(--counter-prefix-color);
  padding-right: 0px;
