#toast-container > .toast {
  position: relative;
  overflow: visible !important;
}
/*————弹窗————*/
/*@hr*/
#toast-container > .toast {
    background-image: none !important;
    background: rgba(0, 0, 0,0.7) !important;
    border: 1.5px solid #9BBFFF;
    border-radius: 20px ;
    box-shadow: 
  inset -0px -3px 3px rgba(245, 189, 206, 0),
  0px 6px 5px rgba(255, 255, 255, 0),
  0px 0px 28px rgba(61, 109, 184, 0.4);
    opacity: 1 !important;    /* 设置透明度 */
    padding: 10px 15px 10px 50px; /* 调整内边距，上-右-下-左 */
    min-height: 30px;/* 通知框最小高度 */ 
    max-width: 260px;/* 通知框最大宽度 */

}
.toast::after {
    content: '';
    position: absolute;
    right: -5px;/* 右侧图标装饰*/
    bottom: -10px;/* 底部的位置 */
    width: 40px;/* 宽度 */
    height: 40px;/* 高度  */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}
.toast::before {
    content: '';
    position: absolute;
    left: 16px;/* 设置图标距离左边的位置 */
    top: 50%;/* 垂直居中对齐 */
    transform: translateY(-50%);
    width: 13px;/* 宽度 */
    height: 13px;/* 高度 */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

/* 成功 (Success) 通知的自定义图标 */
